// Composition-root smoke test: runs the real `initializeInjector()` that
// `bootstrap()` calls before `runApp()`.
//
// A green run proves the DI graph *builds*: every module registers without a
// duplicate, every eager resolution finds its dependency, and no package does
// platform I/O that its own test prerequisite does not cover. It does not prove
// the graph is *correct*: lazy registrations nobody resolves here are never
// built, and behaviour is not exercised.
//
// The only setup is `installCompositionRootPrerequisites()`, generated by
// `dart run monorepo_toolkit generate test-harness`. If this test fails with a
// `MissingPluginException`, the package that touches the plugin must declare
// an `archipelago: test_prerequisites` entry; do not add a fake here. See
// docs/adr/017-composition-root-test-prerequisites.md.
import 'package:app_utilities/app_utilities.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:logger/logger.dart';
import 'package:router_registry/router_registry.dart';
import 'package:pico/di/injector.dart';

import '../support/composition_root_harness.dart';

void main() {
  setUpAll(() async {
    await installCompositionRootPrerequisites();
    await initializeInjector();
  });

  tearDownAll(getIt.reset);

  test('initializeInjector() populates the container', () {
    expect(getIt.isRegistered<Log>(), isTrue);
    expect(getIt.isRegistered<Logger>(), isTrue);
    expect(getIt.isRegistered<RouteRegistry>(), isTrue);
  });

  test('a lazySingleton (Log) resolves to one instance', () {
    expect(identical(getIt<Log>(), getIt<Log>()), isTrue);
  });

  test('a factory (Logger) resolves to a new instance each time', () {
    expect(identical(getIt<Logger>(), getIt<Logger>()), isFalse);
  });

  // Add project-specific graph invariants below this line.
}
